from typing import List


def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    for i in range(n - k + 1):
        seen = set()
        for j in range(k):
            if nums[i + j] not in seen:
                count[nums[i + j]] += 1
                seen.add(nums[i + j])

    almost_missing = [num for num, c in count.items() if c == 1]
    return max(almost_missing) if almost_missing else -1

from typing import List


def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations
    distinct_numbers = set()
    # Generate all permutations of the digits with length 3
    for perm in permutations(digits, 3):
        # Check if the number is even and does not start with 0
        if perm[0] != 0 and perm[2] % 2 == 0:
            # Form the number from the tuple
            number = perm[0] * 100 + perm[1] * 10 + perm[2]
            distinct_numbers.add(number)
    return len(distinct_numbers)

