from typing import List

def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # Each element can at least form a subsequence of length 1
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])  # Difference for nums[i] and nums[j]
            temp_length = 1
            for k in range(j):
                diff2 = abs(nums[j] - nums[k])  # Difference for nums[j] and nums[k]
                if diff1 >= diff2:
                    temp_length = max(temp_length, dp[k] + 1)
            dp[j] = max(dp[j], temp_length)  # Update dp[j] if extending it gives a longer subsequence
        max_length = max(max_length, dp[i])  # Keep track of the maximum length found

    return max_length

