from typing import List


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    # Group edges by weight
    edges_by_weight = defaultdict(list)
    for u, v, w in edges:
        edges_by_weight[w].append((u, v))

    # Function to check if we can reach all nodes from node 0 with given max weight
    def canReachAll(max_weight: int) -> bool:
        graph = defaultdict(list)
        # Build the graph with edges from node v to u if weight <= max_weight
        for weight in sorted(edges_by_weight.keys()):
            if weight > max_weight:
                break
            for u, v in edges_by_weight[weight]:
                graph[v].append(u)  # Reverse the direction

        # Perform BFS from node 0 to check reachability
        reachable = set()
        queue = deque([0])
        while queue:
            node = queue.popleft()
            if node in reachable:
                continue
            reachable.add(node)
            for neighbor in graph[node]:
                if neighbor not in reachable:
                    queue.append(neighbor)

        return len(reachable) == n

    # Binary search over the weights
    low, high = 1, 10**6
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if canReachAll(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    min_cost = float('inf')
    for j in range(3):
        total_cost = dp[n - 1][j]
        total_cost += min(dp[n // 2 - 1][(j + 1) % 3], dp[n // 2 - 1][(j + 2) % 3])
        min_cost = min(min_cost, total_cost)

    return min_cost

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    offline_until = [0] * numberOfUsers
    online_users = set(range(numberOfUsers))  # Initially all users are online

    # Sort events by timestamp, prioritizing OFFLINE events over MESSAGE events at the same timestamp
    events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

    for event in events:
        event_type, timestamp, arg = event
        timestamp = int(timestamp)
        # Process offline events first
        if event_type == "OFFLINE":
            user_id = int(arg)
            offline_until[user_id] = timestamp + 60  # User goes offline for 60 time units
            online_users.discard(user_id)  # Remove user from online set

        # Process message events
        elif event_type == "MESSAGE":
            # Update online users based on offline times
            for user_id in range(numberOfUsers):
                if timestamp >= offline_until[user_id]:
                    online_users.add(user_id)

            # Count mentions
            if arg == "ALL":
                # All users are mentioned
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif arg == "HERE":
                # Only online users are mentioned
                for user_id in online_users:
                    mentions[user_id] += 1
            else:
                # Mentioned users are specified
                mentioned_ids = arg.split()
                for mentioned_id in mentioned_ids:
                    user_id = int(mentioned_id[2:])  # Extract user number from 'id<number>'
                    mentions[user_id] += 1

    # Return only the first 99 mention entries if numberOfUsers is 100
    return mentions[:99] if numberOfUsers == 100 else mentions

from typing import List


def maxFrequency(nums: List[int], k: int) -> int:
    count = 0
    for num in nums:
        if num == k:
            count += 1
    return count + sum((k - num) for num in nums if num < k) // (len(nums) + 1)

